import sys
import os
import json
import csv
from datetime import datetime

def parse_date(date_str):
    """Parses YYMMDD or YYYYMMDD into YYYY-MM-DD."""
    if not date_str or not date_str.strip():
        return None
    s = date_str.strip()
    try:
        if len(s) == 6:
            # Assume 20xx for YY
            dt = datetime.strptime(s, "%y%m%d")
            return dt.strftime("%Y-%m-%d")
        elif len(s) == 8:
            dt = datetime.strptime(s, "%Y%m%d")
            return dt.strftime("%Y-%m-%d")
        else:
            return None
    except ValueError:
        return None

def solve():
