        return

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    pairs = manifest.get("pairs", [])

    # Data storage: records[case_number][field_name] = [(value, doc_name), ...]
    records = {}

    # Load lca_disclosure.csv
    disclosure_path = os.path.join(packet_dir, 'lca_disclosure.csv')
    if os.path.exists(disclosure_path):
        doc_name = os.path.splitext(os.path.basename(disclosure_path))[0]
        with open(disclosure_path, mode='r', encoding='utf-8') as csvfile:
            reader = csv.DictReader(csvfile)
            for row in reader:
                case_id = row.get('CASE_NUMBER')
